74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    /**
80	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
81	     * carrying the new owner's id, customer code and registration date.
82	     */
83	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
84	
85	    /**
86	     * Source of the {@code seq} carried by each {@link OwnerCreatedEvent}: a monotonically increasing
87	     * counter bumped once per successful create, so every emitted event carries a strictly larger
88	     * sequence number than the create before it.
89	     */
90	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
91	
92	    /**
93	     * Maximum number of owners a single city may hold. A create whose city already contains this many
94	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
95	     */
96	    private static final int MAX_OWNERS_PER_CITY = 50;
97	
98	    /**
99	     * Maximum number of owners that may be registered in a single day. A create made once this many
100	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
101	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
102	     */
103	    private static final int MAX_OWNERS_PER_DAY = 100;
104	
105	    /**
106	     * The number of owners that must already carry a given day's {@code registrationDate} before a
107	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
108	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
109	     */
110	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
111	
112	    /**
113	     * Request header carrying the client-supplied idempotency key for a create. When a create repeats
114	     * with a key already seen, the originally created owner is returned with {@code 200 OK} instead of
115	     * creating a duplicate (see {@link #addOwner}).
116	     */
117	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
118	
119	    /**
120	     * Remembers, per seen {@code Idempotency-Key}, the id of the owner that create originally produced,
121	     * so a repeated create carrying the same key replays that owner rather than creating a duplicate.
122	     */
123	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
124	
