143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
146	        Collection<Owner> owners;
147	        if (lastName != null) {
148	            owners = this.clinicService.findOwnerByLastName(lastName);
149	        } else {
150	            owners = this.clinicService.findAllOwners();
151	        }
152	        if (owners.isEmpty()) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
156	    }
