168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
171	        String idempotencyKey = idempotencyKey();
172	        if (idempotencyKey != null) {
173	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
174	            if (existingId != null) {
175	                Owner existing = this.clinicService.findOwnerById(existingId);
176	                if (existing != null) {
177	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
178	                }
179	            }
180	        }
181	        normalizeAddress(ownerFieldsDto);
182	        rejectBlankOwnerFields(ownerFieldsDto);
183	        rejectInvalidPostcode(ownerFieldsDto);
184	        normalizeTelephone(ownerFieldsDto);
185	        normalizeEmail(ownerFieldsDto);
186	        String householdId = householdIdFor(ownerFieldsDto);
187	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
188	        rejectDuplicateIdentity(ownerFieldsDto);
189	        rejectCityAtCapacity(ownerFieldsDto.getCity());
190	        rejectFutureRegistrationDate(ownerFieldsDto.getRegistrationDate());
191	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
192	        long registeredThatDay = countRegisteredOn(registrationDate);
193	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
194	        HttpHeaders headers = new HttpHeaders();
195	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
196	        owner.setRegistrationDate(registrationDate);
197	        owner.setHouseholdId(householdId);
198	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
199	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
200	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
201	        owner.setMembershipLevel(cappedMembershipLevel(owner));
202	        markPossibleDuplicate(owner, sharesHousehold);
203	        this.clinicService.saveOwner(owner);
204	        if (idempotencyKey != null) {
205	            this.idempotentCreates.put(idempotencyKey, owner.getId());
206	        }
207	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
208	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
209	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
210	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
211	        OwnerCreatedEvent event = new OwnerCreatedEvent(EVENT_SEQ.incrementAndGet(),
212	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
213	        AUDIT.info(event.toJson());
214	        headers.setLocation(UriComponentsBuilder.newInstance()
215	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
216	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
217	    }
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
222	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
223	        if (currentOwner == null) {
224	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	        }
226	        normalizeAddress(ownerFieldsDto);
227	        currentOwner.setAddress(addressFor(ownerFieldsDto));
228	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
229	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
230	        currentOwner.setCity(ownerFieldsDto.getCity());
231	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
232	        currentOwner.setLastName(ownerFieldsDto.getLastName());
233	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
234	        normalizeEmail(ownerFieldsDto);
235	        currentOwner.setEmail(ownerFieldsDto.getEmail());
236	        currentOwner.setHouseholdId(householdIdFor(ownerFieldsDto));
237	        this.clinicService.saveOwner(currentOwner);
238	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
239	    }
