318	    /**
319	     * The owner's current primary identifier, as carried on the {@link OwnerCreatedEvent} audit event.
320	     * Today an owner is keyed by its {@code customerCode}; when that identifier is later unified into
321	     * the {@code memberId}, this single accessor changes to return the memberId and the emitted event
322	     * carries it in place of the customer code, with no other call site affected.
323	     *
324	     * @param owner the freshly created owner, already stamped with its {@code customerCode}
325	     * @return the owner's current primary identifier
326	     */
327	    private String primaryIdentifier(Owner owner) {
328	        return owner.getCustomerCode();
329	    }
330	
331	    /**
332	     * Reads the optional {@code Idempotency-Key} header from the current request. The generated
333	     * {@code addOwner} signature carries only the request body, so the header is pulled from the
334	     * request bound to the current thread. Returns the trimmed key, or {@code null} when the header is
335	     * absent or blank (in which case the create proceeds normally, without idempotent replay).
336	     *
337	     * @return the non-blank idempotency key, or {@code null} when none was supplied
338	     */
339	    private String idempotencyKey() {
340	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
341	            return null;
342	        }
343	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
344	        return isBlank(key) ? null : key.trim();
345	    }
346	
347	    /**
348	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
349	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
350	     * the request body already rejects null and empty values, but permits whitespace-only strings
351	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
352	     * that gap so every required field must carry a non-blank value.
353	     *
354	     * @param ownerFieldsDto the submitted owner fields
355	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
356	     */
357	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
358	        List<String> missing = new ArrayList<>();
359	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
360	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
361	        if (isBlank(ownerFieldsDto.getAddressLine1()) && isBlank(ownerFieldsDto.getAddress())) {
362	            missing.add("address");
363	        }
364	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
365	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
366	        if (!missing.isEmpty()) {
367	            throw new InvalidOwnerFieldsException(missing);
368	        }
369	    }
370	
371	    /**
372	     * Rejects an owner whose supplied {@code postcode} is invalid for its {@code city}. The postcode is
373	     * optional: when absent (null) the owner is accepted unchanged, so the request contract stays
374	     * backward-compatible. When present it must be four digits and, when the city maps to a known region,
375	     * must fall within that region's fixed inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
376	     * {@code QLD 4000-4099}); a city with no known region accepts any 4-digit postcode. See
377	     * {@link PostcodeValidator}.
378	     *
379	     * @param ownerFieldsDto the submitted owner fields (its {@code city} is non-blank here,
380	     *                       {@link #rejectBlankOwnerFields} having already run)
381	     * @throws InvalidOwnerFieldsException if a postcode is present but not valid for the city
382	     */
383	    private void rejectInvalidPostcode(OwnerFieldsDto ownerFieldsDto) {
384	        if (!PostcodeValidator.isValid(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode())) {
385	            throw new InvalidOwnerFieldsException(List.of("postcode"));
386	        }
387	    }
388	
389	    private void addIfBlank(List<String> missing, String fieldName, String value) {
390	        if (isBlank(value)) {
391	            missing.add(fieldName);
392	        }
393	    }
394	
395	    private boolean isBlank(String value) {
396	        return value == null || value.isBlank();
397	    }
398	
399	    /**
400	     * Normalizes the submitted address on create to its canonical form (see
401	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
402	     * stored and returned, and the form every later address comparison (the required-field check,
403	     * household duplicate detection and the shared household id) is judged on. The structured fields
404	     * are preferred: {@code addressLine1} and the optional {@code addressLine2} are each normalized in
405	     * place, and the flat {@code address} is set to the {@linkplain #composedAddress composed} value
406	     * derived from them when a structured {@code addressLine1} is present, falling back to the
407	     * normalized flat {@code address} otherwise. Any absent field is left absent so
408	     * {@link #rejectBlankOwnerFields} still reports a wholly missing address; a value that is blank
409	     * after normalization likewise reduces to the empty string and is rejected there.
410	     *
411	     * @param ownerFieldsDto the submitted owner fields
412	     */
413	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
414	        String addressLine1 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine1());
415	        String addressLine2 = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddressLine2());
416	        String flatAddress = AddressNormalizer.normalizeOrNull(ownerFieldsDto.getAddress());
417	        ownerFieldsDto.setAddressLine1(addressLine1);
418	        ownerFieldsDto.setAddressLine2(addressLine2);
419	        ownerFieldsDto.setAddress(composedAddress(addressLine1, addressLine2, flatAddress));
420	    }
421	
422	    /**
423	     * Composes the flat {@code address} an owner should carry from its (already normalized) address
424	     * fields, preferring the structured form. When a non-blank {@code addressLine1} is present the
425	     * composed address is {@code addressLine1}, with a single space and {@code addressLine2} appended
426	     * when {@code addressLine2} is present; otherwise the flat {@code address} is used unchanged. This
427	     * is the single value every later reader of the address (the required-field check, household
428	     * duplicate detection and the shared household id) is judged on.
429	     *
430	     * @param addressLine1 the normalized first address line, or {@code null}/blank when absent
431	     * @param addressLine2 the normalized second address line, or {@code null}/blank when absent
432	     * @param flatAddress  the normalized flat address, or {@code null}/blank when absent
433	     * @return the composed flat address, or {@code null} when no address form was supplied
434	     */
435	    private String composedAddress(String addressLine1, String addressLine2, String flatAddress) {
436	        if (isBlank(addressLine1)) {
437	            return flatAddress;
438	        }
439	        if (isBlank(addressLine2)) {
440	            return addressLine1;
441	        }
442	        return addressLine1 + " " + addressLine2;
443	    }
444	
445	    /**
446	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
447	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
448	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
449	     * {@code 400 Bad Request}.
450	     *
451	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
452	     *                       {@link #rejectBlankOwnerFields} having already run)
453	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
454	     */
455	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
456	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
457	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
458	        ownerFieldsDto.setTelephone(normalized);
459	    }
460	
461	    /**
462	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
463	     * untouched (email is optional). When present it is reduced to its canonical form (see
464	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
465	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
466	     *
467	     * @param ownerFieldsDto the submitted owner fields
468	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address,
469	     *                                     or its domain is on the disposable-domain blocklist
470	     */
471	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
472	        String email = ownerFieldsDto.getEmail();
473	        if (email == null || email.isBlank()) {
474	            return;
475	        }
476	        String normalized = EmailNormalizer.normalize(email)
477	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
478	        if (EmailNormalizer.hasDisposableDomain(normalized)) {
479	            throw new InvalidOwnerFieldsException(List.of("email"));
480	        }
481	        ownerFieldsDto.setEmail(normalized);
482	    }
483	
484	    /**
485	     * Rejects creating an owner whose derived identity collides with an existing owner. All owner
486	     * duplicate detection is now expressed through the single derived {@code identityKey}
487	     * ({@code sha256hex(normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))}, see
488	     * {@link OwnerIdentity}), which replaces the previously separate telephone, email and household
489	     * checks. Two owners denote the same person when their whole identity keys are equal, so a create
490	     * is rejected as a {@code 409 Conflict} when another (non-deleted) owner already carries the same
491	     * key. Because the telephone is part of the key, two owners who share a last name and postcode but
492	     * carry different telephones have different keys and are both allowed (they are instead recorded as
493	     * a {@linkplain #findPossibleDuplicate possible duplicate}); an email or a household on its own no
494	     * longer makes a duplicate.
495	     *
496	     * @param ownerFieldsDto the submitted owner fields, with telephone and email already normalized
497	     *                       ({@link #normalizeTelephone}, {@link #normalizeEmail})
498	     * @throws DuplicateOwnerIdentityException if another owner already carries the same identity
499	     */
500	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
501	        String identityKey = OwnerIdentity.identityKey(
502	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(), ownerFieldsDto.getLastName());
503	        boolean inUse = activeOwners().stream()
504	            .map(OwnerIdentity::identityKey)
505	            .anyMatch(identityKey::equals);
506	        if (inUse) {
507	            throw new DuplicateOwnerIdentityException(identityKey);
508	        }
509	    }
510	
511	    /**
512	     * The owners considered by duplicate detection: every persisted owner except those flagged
513	     * {@code deleted}. A soft-deleted owner is retained but must never make a later create look like a
514	     * duplicate, so both the hard-duplicate identity check ({@link #rejectDuplicateIdentity}) and the
515	     * soft {@linkplain #findPossibleDuplicate possible-duplicate} match are judged against these owners
516	     * alone. Only owners already persisted (before this create) are included.
517	     *
518	     * @return the non-deleted owners currently persisted
519	     */
520	    private List<Owner> activeOwners() {
521	        return this.clinicService.findAllOwners().stream()
522	            .filter(owner -> !owner.isDeleted())
523	            .toList();
524	    }
525	
526	    /**
527	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
528	     * both match the submitted values, compared case-insensitively. The count reflects only owners
529	     * already persisted at the time of the create, so the owner being created is never included.
530	     *
531	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
532	     *                  having already run)
533	     * @param lastName  the submitted last name (non-blank here)
534	     * @return the number of existing owners sharing the same first and last name
535	     */
536	    private int countNamesakes(String firstName, String lastName) {
537	        return (int) this.clinicService.findAllOwners().stream()
538	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
539	                && lastName.equalsIgnoreCase(owner.getLastName()))
540	            .count();
541	    }
542	
543	    /**
544	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
545	     * whose stored {@code householdId} equals the value derived for the owner being created. The
546	     * count reflects only owners already persisted at the time of the create, so the owner being
547	     * created is never included; callers add one to obtain the household size after this create.
548	     *
549	     * @param householdId the household identifier derived for the owner being created (see
550	     *                    {@link HouseholdNormalizer#toHouseholdId})
551	     * @return the number of existing owners already sharing that household
552	     */
553	    private int countHouseholdMembers(String householdId) {
554	        return householdMembers(householdId).size();
555	    }
556	
557	    /**
558	     * Returns the existing owners (before this create) belonging to the given household, i.e. those
559	     * whose stored {@code householdId} equals the value derived for the owner being created. As with
560	     * {@link #countHouseholdMembers}, only owners already persisted are included, so the owner being
561	     * created is never among them.
562	     *
563	     * @param householdId the household identifier derived for the owner being created (see
564	     *                    {@link HouseholdNormalizer#toHouseholdId})
565	     * @return the existing owners already sharing that household (empty when {@code householdId} is
566	     *         {@code null})
567	     */
568	    private List<Owner> householdMembers(String householdId) {
569	        if (householdId == null) {
570	            return List.of();
571	        }
572	        return this.clinicService.findAllOwners().stream()
573	            .filter(member -> householdId.equals(member.getHouseholdId()))
574	            .toList();
575	    }
576	
577	    /**
578	     * Caps a new owner's {@code membershipLevel} so it cannot exceed one above the current maximum
579	     * {@code membershipLevel} among their existing household members. The owner's own level is the
580	     * value {@linkplain OwnerMapper#membershipLevel(Owner) it would otherwise report}; it is capped at
581	     * {@code maxHouseholdLevel + 1}. When the household has no existing member no cap applies and the
582	     * owner's own level is returned unchanged.
583	     *
584	     * @param owner the owner being created, already stamped with its household id and size
585	     * @return the (possibly capped) membership level to stamp on the owner
586	     */
587	    private int cappedMembershipLevel(Owner owner) {
588	        int ownLevel = this.ownerMapper.membershipLevel(owner);
589	        OptionalInt maxHouseholdLevel = householdMembers(owner.getHouseholdId()).stream()
590	            .mapToInt(this.ownerMapper::membershipLevel)
591	            .max();
592	        return maxHouseholdLevel.isPresent()
593	            ? Math.min(ownLevel, maxHouseholdLevel.getAsInt() + 1)
594	            : ownLevel;
595	    }
596	
597	    /**
598	     * Derives the address an owner should carry from its submitted fields. The update path stamps an
599	     * owner with an address taken from the request, so routing that through this single method keeps the
600	     * derivation of "the owner's address" in one place, mirroring {@link #householdIdFor} for the
601	     * household id.
602	     *
603	     * @param ownerFieldsDto the submitted owner fields
604	     * @return the address to store on the owner
605	     */
606	    private String addressFor(OwnerFieldsDto ownerFieldsDto) {
607	        return ownerFieldsDto.getAddress();
608	    }
609	
610	    /**
611	     * Derives the household id an owner should carry from its submitted fields (see
612	     * {@link HouseholdNormalizer#toHouseholdId}). Both create and update stamp an owner with a
613	     * household id, so routing them through this single method keeps them agreed on which of the
614	     * owner's fields key the household.
615	     *
616	     * @param ownerFieldsDto the submitted owner fields (its identifying fields are non-blank here,
617	     *                       {@link #rejectBlankOwnerFields} having already run on create)
618	     * @return the owner's household id
619	     */
620	    private String householdIdFor(OwnerFieldsDto ownerFieldsDto) {
621	        return HouseholdNormalizer.toHouseholdId(
622	            ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
623	    }
624	
625	    /**
626	     * Finds an existing owner that the owner being created soft-matches on, or {@code null} when there
627	     * is none. The create has already cleared the hard-duplicate identity check
628	     * ({@link #rejectDuplicateIdentity}), so its {@code identityKey} matches no existing owner; it is a
629	     * <em>possible</em> duplicate when it nevertheless shares an existing owner's {@code postcode} and
630	     * the {@linkplain Soundex#soundex Soundex} of its {@code lastName} while their identity keys still
631	     * differ. Because the telephone is part of the identity key, two owners with the same last name and
632	     * postcode but different telephones have differing keys and so soft-match here rather than colliding
633	     * as a hard duplicate. The oldest such owner (the earliest persisted) is returned so the flag points
634	     * at the original record; owners with no postcode never match, since a shared postcode is required.
635	     *
636	     * @param owner the owner being created, with telephone already normalized and lastName/postcode set
637	     * @return the id of the matching existing owner, or {@code null} when the owner is not a possible
638	     *         duplicate
639	     */
640	    private Integer findPossibleDuplicate(Owner owner) {
641	        String postcode = owner.getPostcode();
642	        if (postcode == null) {
643	            return null;
644	        }
645	        String identityKey = OwnerIdentity.identityKey(owner);
646	        String lastNameCode = Soundex.soundex(owner.getLastName());
647	        return activeOwners().stream()
648	            .filter(existing -> !identityKey.equals(OwnerIdentity.identityKey(existing)))
649	            .filter(existing -> lastNameCode.equals(Soundex.soundex(existing.getLastName())))
650	            .filter(existing -> postcode.equals(existing.getPostcode()))
651	            .map(Owner::getId)
652	            .filter(Objects::nonNull)
653	            .min(Integer::compareTo)
654	            .orElse(null);
655	    }
656	
657	    /**
658	     * Records on the owner being created whether it is a possible (soft) duplicate of an existing
659	     * owner. The match itself is decided by {@link #findPossibleDuplicate}; this method reflects its
660	     * result into the two stored fields, so the interpretation of "is a possible duplicate" lives in
661	     * one place: {@code possibleDuplicateOf} holds the matched owner's id (or {@code null} when there
662	     * is none) and {@code possibleDuplicate} is {@code true} exactly when a match was found. An owner
663	     * that opted in with {@code sharesHousehold} is a declared household member, not a suspected
664	     * duplicate, so it is never flagged.
665	     *
666	     * @param owner           the owner being created, with telephone already normalized and
667	     *                        lastName/postcode set
668	     * @param sharesHousehold whether the request opted in to sharing a household
669	     */
670	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
671	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
672	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
673	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
674	    }
675	
676	    /**
677	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
678	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
679	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
680	     *
681	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
682	     *             run)
683	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
684	     */
685	    private void rejectCityAtCapacity(String city) {
686	        long ownersInCity = this.clinicService.findAllOwners().stream()
687	            .map(Owner::getCity)
688	            .filter(Objects::nonNull)
689	            .filter(city::equalsIgnoreCase)
690	            .count();
691	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
692	            throw new OwnerCityAtCapacityException(city);
693	        }
694	    }
695	
696	    /**
697	     * Resolves the effective registration date for a create, rolled onto a business day. The
698	     * supplied date is used when present, otherwise the server's current date; either way the result
699	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
700	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
701	     * stored {@code registrationDate}, the membership number's year segment and the daily
702	     * create-limit's per-day count - is judged on this adjusted date.
703	     *
704	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
705	     *                                 default to the server's current date
706	     * @return the effective registration date, guaranteed to fall on a business day
707	     */
708	    /**
709	     * Rejects a create whose supplied {@code registrationDate} lies after the server's current date.
710	     * The raw submitted value is compared against {@link LocalDate#now()} before any business-day
711	     * adjustment; a future date cannot describe a registration that has already happened, so it is
712	     * reported as a {@code 400 Bad Request}. A {@code null} registration date (defaulted to the
713	     * server's current date) and any date on or before today are accepted.
714	     *
715	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when
716	     *                                 omitted
717	     * @throws InvalidOwnerFieldsException if the supplied date is later than the server's current date
718	     */
719	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
720	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
721	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
722	        }
723	    }
724	
725	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
726	        LocalDate registrationDate =
727	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
728	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
729	    }
730	
731	    /**
732	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
733	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
734	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
735	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
736	     * Too Many Requests}.
737	     *
738	     * @param registrationDate   the create's effective registration date, already rolled onto a
739	     *                           business day by {@link #effectiveRegistrationDate}
740	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
741	     *                           {@code registrationDate} equals {@code registrationDate}
742	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
743	     *                                              owner registrations
744	     */
745	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
746	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
747	            throw new OwnerDailyRegistrationLimitException(registrationDate);
748	        }
749	    }
750	
751	    /**
752	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
753	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
754	     * bulk-signup warning are judged on.
755	     *
756	     * @param registrationDate the create's effective registration date, already rolled onto a business
757	     *                         day by {@link #effectiveRegistrationDate}
758	     * @return the number of existing owners registered on that day
759	     */
760	    private long countRegisteredOn(LocalDate registrationDate) {
761	        return this.clinicService.findAllOwners().stream()
762	            .map(Owner::getRegistrationDate)
763	            .filter(registrationDate::equals)
764	            .count();
765	    }
766	}
