21	/**
22	 * Thrown when a request to create an owner would exceed a city's capacity - that is, the city already
23	 * holds the maximum permitted number of owners. Unlike the {@link DuplicateOwnerException} family this
24	 * is a capacity limit rather than a uniqueness collision, but it is likewise reported to the client as
25	 * a {@code 409 Conflict}. Carries the offending city and the client-facing detail so the
26	 * {@link ExceptionControllerAdvice} can render the response.
27	 */
28	public class OwnerCityAtCapacityException extends RuntimeException {
29	
30	    private static final String DETAIL = "The owner's city has reached its maximum number of owners";
31	
32	    private final String city;
33	
34	    public OwnerCityAtCapacityException(String city) {
35	        super("City already at owner capacity: " + city);
36	        this.city = city;
37	    }
38	
39	    public String getCity() {
40	        return this.city;
41	    }
42	
43	    public String getDetail() {
44	        return DETAIL;
45	    }
46	
47	    public List<String> getErrorFields() {
48	        return List.of("city");
49	    }
50	}
